import{_ as a,o as t,c as e,ak as i,an as d,ao as l,ap as r,aq as s}from"./chunks/framework.C5PBIMEM.js";const G=JSON.parse('{"title":"Godot 4 创建第一个场景并运行项目","description":"","frontmatter":{"0":"i","1":"n","2":"d","3":"e","4":"x","5":":","6":"2"},"headers":[],"relativePath":"godot/godot-4-first-scene.md","filePath":"godot/godot-4-first-scene.md","lastUpdated":1780926050000}'),n={name:"godot/godot-4-first-scene.md"};function p(c,o,h,_,m,g){return t(),e("div",null,[...o[0]||(o[0]=[i('<h1 id="godot-4-创建第一个场景并运行项目" tabindex="-1">Godot 4 创建第一个场景并运行项目 <a class="header-anchor" href="#godot-4-创建第一个场景并运行项目" aria-label="Permalink to “Godot 4 创建第一个场景并运行项目”">​</a></h1><p>本教程适用于搜索以下问题的用户：</p><ul><li>Godot 创建场景</li><li>Godot Node2D</li><li>Godot 主场景</li><li>Godot 运行项目</li><li>Godot 第一个项目怎么运行</li></ul><p>Godot 的开发方式非常核心的一点，就是 <strong>先做场景，再做游戏逻辑</strong>。<br> 如果你刚创建完项目，下一步就是先做一个最基础的场景。</p><h2 id="一、新建场景" tabindex="-1">一、新建场景 <a class="header-anchor" href="#一、新建场景" aria-label="Permalink to “一、新建场景”">​</a></h2><p>在编辑器中创建一个新的场景。</p><p><img src="'+d+'" alt="Godot 4 Windows 创建场景页面"></p><h2 id="二、添加根节点" tabindex="-1">二、添加根节点 <a class="header-anchor" href="#二、添加根节点" aria-label="Permalink to “二、添加根节点”">​</a></h2><p>一般可以从以下节点开始：</p><ul><li><code>Node2D</code>：适合 2D 游戏</li><li><code>Control</code>：适合 UI 界面</li><li><code>Node3D</code>：适合 3D 游戏</li></ul><p>如果你是第一次接触 Godot，建议先从 <strong>Node2D</strong> 开始。</p><p><img src="'+l+'" alt="Godot 4 Windows 新建场景页面"></p><h2 id="三、点击运行" tabindex="-1">三、点击运行 <a class="header-anchor" href="#三、点击运行" aria-label="Permalink to “三、点击运行”">​</a></h2><p>点击编辑器右上角的运行按钮，或者按快捷键运行项目。</p><p><img src="'+r+'" alt="Godot 4 Windows 编辑器运行按钮"></p><p>如果显示如下，请点击：<strong>选择当前</strong></p><p><img src="'+s+'" alt="Godot 4 Windows 编辑器首次运行选择场景"></p><h2 id="四、运行成功后会发生什么" tabindex="-1">四、运行成功后会发生什么 <a class="header-anchor" href="#四、运行成功后会发生什么" aria-label="Permalink to “四、运行成功后会发生什么”">​</a></h2><p>如果一切正常，你就已经成功完成了：</p><ul><li>创建场景</li><li>添加根节点</li><li>设置主场景</li><li>运行项目</li></ul><p>这意味着你的 Godot 环境已经可以正常使用了。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>到这里，你已经完成了 Godot 最基础的入门流程。</p>',23)])])}const b=a(n,[["render",p]]);export{G as __pageData,b as default};
